import ast,json
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
p['study']['alternative_explanations'].append('Earlier task splits do not establish the present hypothesis: r0033 cart/fav-context-only=0.66689148 and buy-only=0.66664263; r0044 product-cart/fav-only=0.66794155 and buy-only=0.66754723. Those different context-edge interventions favored cart/fav over buy. They are historical counterevidence to any broad assertion that buy is always the useful auxiliary task, not matched controls for this summary-projection VJP question.')
p['study']['nearest_work'][3]['difference']=p['study']['nearest_work'][3]['difference'].replace('PDF, pages1-3,','PDF abstract/introduction/related-work excerpts (pages1-3),')
p['study']['proposed_difference']+=' Trajectory review: initial compressed-task transplantation r0006=0.65919424 underperformed both imported source bests (0.66064694 and0.66016336); it was a predictive failure with successful execution. r0050 content-key transfer=0.66791389 lost to its blocked control=0.66828885, so auxiliary transfer is not uniformly beneficial across architectures. r0052 native block nonlinear summary remains best0.66852687. r0066 summary removal=0.66799921 and query removal=0.66834032, r0067 norm restoration=0.66799933 and native rescaling=0.66816467, and all three r0068 modified paths failed to beat native. Repeated native endpoint equality at one seed establishes reproducibility only, not independent repeated mechanism support. The available trajectory index reports successful execution for every recorded trial; weaker prediction is distinguished from missing data or execution failure. Failed official validate_task.py registry resolution this turn is preparation failure only; its costs remain charged.'
checks='''Host prerequisites before training: confirm frozen protocol/data identities, released digests and existing loader/readiness receipts; no raw data is available locally. Verify four finite [B,1] outputs, unweighted sum BCE and finite native FP32/BF16 backward. At common nonzero output weights and all24 label-order permutations, route exactly cart/fav and buy by schema identity. Verify _SummaryProductVJP query derivative v*s; selected summary derivative native v*q or norm-restored ((v-mean(v))*q) with inherited zero-direction fallback, after the unchanged live RMS Jacobian. Native mode must match analytic/native autograd; transformed mode intentionally need not pass finite-difference gradcheck and is first-order only. Verify requested per-example summary norm, finite zero/near-zero/large signed gradients and no extra state/RNG. Verify source ownership per-task: auxiliary summary/item/target/scorer inputs detached, tower context blocked, adapter context enabled. Do not misinterpret task-specific history-projection updates as direct shared-embedding gradients. Check empty, singleton, full and noncontiguous history masks, invalid-history perturbations, unknown target action, sparse repeated-ID accumulation, construction/RNG equality, parameter counts, buffers and checkpoint/device roundtrip. Common-state forward/buffer/gradient and one-step parity must hold between cell00 and r0068 native, and between cell11 and r0068 all-aux, within declared FP32/BF16 tolerance. Any failure blocks interpretation. Use host-authorized diagnostics only; record missing mediators explicitly. Measure all four task AUC/Logloss and auxiliary mean separately, full-population samples/positives/negatives, fixed history slices with counts, total/embedding/dense params, train/allocatedGPU/wall seconds, examples processed, peak memory, inference throughput and p50/p95 batch latency. History bins: empty,1..16,17..64,>64; slice conclusions exploratory; insufficient slices marked. Selection uses only full-validation click AUC. Host-only paired user-cluster bootstrap if available; otherwise state absence, never assume independent exposures. Keep frozen host clipping/optimizer/data/scoring untouched. Stop task splitting if neither selective cell wins. No held-out feedback is authorized in this phase.'''
local='''Completed source checks: all four modules py_compile; standard-library recursive check passes the runtime study schema; protocol, parent and evidence IDs authorized; literal CONFIG matches every constructor default; four ASTs identical except the two declared modes and CONFIG; inherited _SummaryProductVJP, every Model method except constructor/mode routing, and all nn constructor expressions/order preserved exactly. All8 read-only ancestor source digests and baseline_reference.py digest preserved. PyTorch and jsonschema unavailable; official validator is not a registered reference. No tensor/autograd/data/performance test has run locally. Reproduce static compilation with: python3 -m py_compile candidate.py control_buy_summary_direction.py control_all_summary_direction.py control_native_summary.py. Host consumes proposal.json through the supplied propose interface; no invented training CLI. No separate writable memory endpoint is provided: these prospective evidence-linked notes and observed local checks are retained in proposal.json for append-only host receipt ingestion, while read-only evidence.jsonl, knowledge snapshots and ancestors remain intact. No personal knowledge is enabled. All failed preparations and checks consume the host ledger; no hard limit is changed.'''
for v in p['variants']:
 v['note']+=' '+checks+' '+local
# Verify predecessor auxiliary source differs from its native bridge only in its declared mode/default.
def normalized(path):
 tree=ast.parse(Path(path).read_text())
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): n.value=ast.Constant(None)
  if isinstance(n,ast.ClassDef) and n.name=='Model':
   init=next(m for m in n.body if isinstance(m,ast.FunctionDef) and m.name=='__init__')
   for i,a in enumerate(init.args.args[-len(init.args.defaults):]):
    if a.arg in ('primary_summary_vjp','auxiliary_summary_vjp'):init.args.defaults[i]=ast.Constant(None)
 return ast.dump(tree,include_attributes=False)
assert normalized('history_g0_r0068_native_summary_bridge.py')==normalized('history_g0_r0068_auxiliary_summary_direction.py')
Path('proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
print('Added host gates, evidence-linked local checks, negative-trajectory review and explicit memory/performance limits. Verified r0068 predecessor implementation parity.')
PY"

